:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --primary: #6c5ce7;
  --accent: #00cec9;
  --text: #f5f6fa;
  --danger: #e17055;
  --success: #00b894;
  --focus: #fdcb6e;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
  color: var(--text);
}

.card {
  background: var(--card-bg);
  border-radius: 24px;
  padding: 32px 24px;
  max-width: 420px;
  width: 100%;
  box-shadow: 0 12px 30px rgba(0,0,0,0.5);
  text-align: center;
}

h1 {
  font-size: 1.8rem;
  margin-bottom: 24px;
  letter-spacing: 1px;
  color: var(--accent);
}

.inputs {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin-bottom: 24px;
}

.input-group {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  flex: 1;
}

label {
  font-size: 1rem;
  margin-bottom: 6px;
  color: var(--text);
  opacity: 0.8;
}

input[type="number"] {
  width: 100%;
  padding: 12px;
  font-size: 1.4rem;
  border: 2px solid transparent;
  border-radius: 12px;
  background: #3a3a55;
  color: var(--text);
  text-align: center;
  transition: border-color 0.2s, box-shadow 0.2s;
}

input[type="number"]:focus {
  outline: none;
  border-color: var(--focus);
  box-shadow: 0 0 0 3px rgba(253, 203, 110, 0.3);
}

.display {
  font-size: 5rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  letter-spacing: 4px;
  margin: 24px 0 8px;
  color: var(--text);
  text-shadow: 0 0 20px rgba(108, 92, 231, 0.5);
  line-height: 1.2;
}

.message {
  min-height: 2rem;
  font-size: 1.5rem;
  font-weight: 600;
  color: var(--success);
  margin-bottom: 16px;
  transition: opacity 0.3s;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  flex: 1;
  min-width: 100px;
  padding: 14px 20px;
  font-size: 1.2rem;
  font-weight: 600;
  border: none;
  border-radius: 14px;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s, box-shadow 0.2s;
  color: #fff;
  background: var(--primary);
  box-shadow: 0 4px 0 #4a3f9e;
}

.btn:hover {
  background: #7e6ff0;
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.btn:active {
  transform: translateY(3px);
  box-shadow: 0 1px 0 #4a3f9e;
}

.btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  transform: none;
  box-shadow: 0 4px 0 #4a3f9e;
  background: var(--primary);
}

.btn.start {
  background: var(--success);
  box-shadow: 0 4px 0 #007a5e;
}

.btn.start:hover:not(:disabled) {
  background: #00d1a6;
}

.btn.pause {
  background: var(--danger);
  box-shadow: 0 4px 0 #b85a3e;
}

.btn.pause:hover:not(:disabled) {
  background: #f08a6a;
}

.btn.reset {
  background: #636e72;
  box-shadow: 0 4px 0 #3d4446;
}

.btn.reset:hover:not(:disabled) {
  background: #7a8589;
}

@media (max-width: 400px) {
  .display {
    font-size: 3.5rem;
    letter-spacing: 2px;
  }
  .card {
    padding: 24px 16px;
  }
  .btn {
    font-size: 1rem;
    padding: 12px 12px;
  }
}

const minutesInput = document.getElementById('minutes');
const secondsInput = document.getElementById('seconds');
const display = document.getElementById('display');
const message = document.getElementById('message');
const startBtn = document.getElementById('start');
const pauseBtn = document.getElementById('pause');
const resetBtn = document.getElementById('reset');

let totalSeconds = 0;
let remainingSeconds = 0;
let timerInterval = null;
let isRunning = false;

function formatTime(seconds) {
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
}

function updateDisplay() {
  display.textContent = formatTime(remainingSeconds);
}

function setControls(running) {
  isRunning = running;
  startBtn.disabled = running;
  pauseBtn.disabled = !running;
  resetBtn.disabled = !running && remainingSeconds === totalSeconds && totalSeconds === 0;
  // Reset enabled if there is any time set or running
  if (!running && remainingSeconds > 0) resetBtn.disabled = false;
  if (running) resetBtn.disabled = false;
}

function startTimer() {
  if (isRunning) return;
  let mins = parseInt(minutesInput.value, 10) || 0;
  let secs = parseInt(secondsInput.value, 10) || 0;
  if (secs > 59) secs = 59;
  if (mins < 0) mins = 0;
  if (secs < 0) secs = 0;
  minutesInput.value = mins;
  secondsInput.value = secs;
  totalSeconds = mins * 60 + secs;
  if (totalSeconds <= 0) {
    message.textContent = 'Please set a time.';
    return;
  }
  remainingSeconds = totalSeconds;
  message.textContent = '';
  updateDisplay();
  setControls(true);
  timerInterval = setInterval(() => {
    remainingSeconds--;
    updateDisplay();
    if (remainingSeconds <= 0) {
      clearInterval(timerInterval);
      timerInterval = null;
      setControls(false);
      startBtn.disabled = false;
      pauseBtn.disabled = true;
      resetBtn.disabled = false;
      message.textContent = "Time's up!";
    }
  }, 1000);
}

function pauseTimer() {
  if (!isRunning) return;
  clearInterval(timerInterval);
  timerInterval = null;
  setControls(false);
}

function resetTimer() {
  clearInterval(timerInterval);
  timerInterval = null;
  isRunning = false;
  remainingSeconds = 0;
  totalSeconds = 0;
  minutesInput.value = 0;
  secondsInput.value = 0;
  display.textContent = '00:00';
  message.textContent = '';
  startBtn.disabled = false;
  pauseBtn.disabled = true;
  resetBtn.disabled = true;
}

startBtn.addEventListener('click', startTimer);
pauseBtn.addEventListener('click', pauseTimer);
resetBtn.addEventListener('click', resetTimer);

// Initialize
resetTimer();
